#include "Core.hpp"
#include <iostream>
#include "MonitorTests.hpp"
int main(int argc,char** argv){using namespace udm;try{if(argc==3&&(std::string(argv[1])=="--broker-test"||std::string(argv[1])=="--broker-protocol-test")){auto report=monitorTests(std::string(argv[1])=="--broker-test");std::ofstream output(fs::path(wide(argv[2])));output<<report.dump(2);output.close();if(!output)throw std::runtime_error("Cannot save broker test report.");std::cout<<report.dump(2)<<std::endl;return report["Failed"]==0?0:1;}
if(argc==3&&std::string(argv[1])=="--broker-orphan-fixture"){Monitor fixture;fixture.watch({GetCurrentProcessId()});std::ofstream out(fs::path(wide(argv[2])));out<<fixture.snapshot().dump();out.close();if(!out)throw std::runtime_error("Cannot save orphan fixture handshake.");Sleep(60000);return 0;}
if(argc>1&&std::string(argv[1])=="--diagnose"){std::cout<<diagnostics().dump()<<std::endl;return 0;}if(argc>1&&std::string(argv[1])=="--endpoints"){std::cout<<endpoints().dump()<<std::endl;return 0;}if(argc<2||std::string(argv[1])=="--status"){auto status=diagnostics();std::cout<<status.dump()<<std::endl;return status.value("RuntimeVerified",false)?0:1;}Monitor monitor;if(argc<3||std::string(argv[1])!="--watch")throw std::runtime_error("Usage: --diagnose | --status | --endpoints | --watch PID[,PID...] [seconds]");int seconds=argc>3?std::stoi(argv[3]):10;if(seconds<1||seconds>3600)throw std::runtime_error("Use 1-3600 seconds.");std::map<DWORD,FILETIME> identities;for(auto word:words(argv[2])){DWORD id=(DWORD)std::stoul(word);Handle p(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,id));FILETIME created{},exit{},kernel{},user{};if(!p||!GetProcessTimes(p.h,&created,&exit,&kernel,&user))throw std::runtime_error("Cannot identify selected process.");identities[id]=created;}for(int i=0;i<seconds;++i){std::vector<DWORD> pids;for(auto it=identities.begin();it!=identities.end();){Handle p(OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,it->first));FILETIME created{},exit{},kernel{},user{};if(!p||!GetProcessTimes(p.h,&created,&exit,&kernel,&user)||CompareFileTime(&created,&it->second)!=0)it=identities.erase(it);else{pids.push_back(it->first);++it;}}monitor.watch(pids);std::cout<<monitor.snapshot().dump()<<std::endl;Sleep(1000);}monitor.watch({});return 0;}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
